from adafruit_mcp3xxx.spi import SPIDevice
from gpiozero import SPI, Device

spi = SPI(0, 0, 1000000, 0)

class MCP3208:
    def __init__(self, spi):
        self.spi = SPIDevice(spi, cs0=gpiozero.OutputDevice(0), max_speed_hz=1000000)
        self.mcp = MCP.MCP3208(self.spi)

    def read(self, channel, raw=False):
        if channel < 0 or channel > 7:
            return -1
        try:
            value = self.mcp.read(channel)
            if raw:
                return value
            else:
                return value / 4095.0
        except Exception as e:
            print(f"Error reading from MCP3208: {e}")
            return -1

        finally:
            self.spi.close()


