    mcp = MCP3208(spi)
    for raw in [False, True]:
        value = mcp.read(0, raw)
        if value == -1:
            print("Error reading from MCP3208")
        else:
            print(f"Channel 0, Raw={raw}: {value}")


if __name__ == "__main__":
    main()

