from adafruit_mcp3008 import MCP3008
from adafruit_mcp3008.spi import SPIDev
from adafruit_relay import SPST
from paho.mqtt import client as mqtt_client

class SmartGardenController:
    def __init__(self, spi, moisture_channel, relay_channel):
        self._spi = spi
        self._moisture_channel = moisture_channel
        self._relay = SPST(GPIO, relay_channel)

    def read_moisture(self):
        try:
            return self._spi.read(self._moisture_channel)
        except Exception as e:
            print(f"Error reading moisture: {e}")
            return None

    def run_pump(self, seconds):
        try:
            self._relay.on()
            time.sleep(seconds)
            self._relay.off()
        except Exception as e:
            print(f"Error running pump: {e}")

    def irrigation_cycle(self):
        moisture = self.read_moisture()
        if moisture is not None and moisture > 450:
            self.run_pump(2)
            return True
        return False

    def close(self):
        self._spi.close()
        GPIO.cleanup()

def schedule_cycles(controller, cycle_count, interval_seconds):
