import time
import signal
import spidev
from adafruit_mcp3xxx.mcp3008 import MCP3008
from adafruit_mcp3xxx import MCP3xxx

class GasSensor:
    def __init__(self, spi, cs):
        self.spi = spi
        self.cs = cs
        self.mcp3008 = MCP3008(spi, cs)

    def read(self):
        raw_value = self.mcp3008.read(0)
        return raw_value

    def convert_to_ppm(self, raw_value):
        # This conversion is based on the datasheet of the MQ-2 gas sensor
        # and the behavior of the sensor at different gas concentrations.
        # It may not be accurate for all types of gas sensors.
        return (raw_value * 1000) / 1023

    def alert_level(self, ppm):
        if ppm < 150:
            return "safe"
        elif 150 <= ppm < 400:
            return "warning"
        else:
            return "danger"

    def sample_and_print(self):
        try:
            while True:
                raw_values = []
                for _ in range(12):
                    try:
                        raw_values.append(self.read())
                        time.sleep(0.5)
                    except OSError as e:
                        print(f"SPI error: {e}")
                        return

                ppm_values = [self.convert_to_ppm(v) for v in raw_values]
                alert_levels = [self.alert_level(v) for v in ppm_values]

                for ppm, level in zip(ppm_values, alert_levels):
                    print(f"PPM concentration: {ppm}, alert level: {level}")
        except KeyboardInterrupt:
            print("\nExiting on user request.")
        finally:
            self.spi.close()

def main():
    spi = spidev.SpiDev()
    spi.open(0, 0)
    sensor = GasSensor(spi, MCP3xxx.SPI_0_CS_0)
    sensor.sample_and_print()

if __name__ == "__main__":
    main()

