def read_adc_channel(adc, channel):
    try:
        return adc.read(channel)
    except OSError as e:
        logging.error(f"Error reading ADC channel: {e}")
        return None

def classify_water_level(percent):
    if percent < 25:
        return "low"
    elif percent < 75:
        return "normal"
    else:
        return "high"

def main():
    with open('water_level_log.csv', 'w', newline='') as file:
        writer = csv.writer(file)
        writer.writerow(["timestamp", "percent", "category"])
        try:
