                raw_value = read_adc_channel(adc, 0)
                if raw_value is not None:
                    percent = raw_value / 1023 * 100
                    category = classify_water_level(percent)
                    writer.writerow([time.time(), percent, category])
                    logging.info(f"Water level: {percent}% ({category})")
                time.sleep(1)
        finally:
            spi.close()

