import os
import time
import signal
import atexit
import traceback
from multiprocessing import Process, Event
from datetime import datetime

class ConsoleWatchdog:
    def __init__(self, console_pid):
        self.console_pid = console_pid
        self.keep_alive = Event()
        self.watchdog_process = Process(target=self.watchdog_loop)
        atexit.register(self.atexit_handler)

    def atexit_handler(self):
        self.send_signal(signal.SIGUSR1)
        time.sleep(3)
        self.send_signal(signal.SIGKILL)

    def send_signal(self, sig):
        try:
            os.kill(self.console_pid, sig)
        except ProcessLookupError:
            pass

    def watchdog_loop(self):
        while True:
            try:
                self.keep_alive.wait(60)
                if self.keep_alive.is_set():
                    self.keep_alive.clear()
                else:
                    self.send_signal(signal.SIGUSR1)
                    time.sleep(3)
                    self.send_signal(signal.SIGKILL)
                with open('/home/pi/Console/.HistoryBuffer/hlogW', 'a') as f:
                    f.write(f'Watchdog failed to receive keep-alive at {datetime.now()}.\n')
                    f.flush()
            except Exception as e:
                with open('/home/pi/Console/.HistoryBuffer/hlogW', 'a') as f:
                    f.write(f'Watchdog exception at {datetime.now()}:\n{str(e)}\n')
                    f.flush()

    def start(self):
        self.watchdog_process.start()

    def stop(self):
        self.watchdog_process.terminate()

def watchdog_signal_handler(sig, frame):
    if sig == signal.SIGTERM:
        with open('/home/pi/Console/.HistoryBuffer/hlogW', 'a') as f:
            f.write(f'Watchdog received SIGTERM at {datetime.now()} from systemd.\n')
            f.flush()
        time.sleep(30)
        os._exit(0)
    elif sig == signal.SIGINT or sig == signal.SIGUSR1:
        os._exit(94)
    elif sig == signal.SIGHUP:
        with open('/home/pi/Console/.HistoryBuffer/hlogW', 'a') as f:
            f.write(f'Watchdog received SIGHUP at {datetime.now()}.\n')
            f.flush()
    elif sig == signal.SIGABRT:
        with open('/home/pi/.tombstoneW', 'w') as f:
            f.write(f'Watchdog aborted at {datetime.now()} with stack trace:\n{traceback.format_exc()}')
        os._exit(93)

def main():
    console_pid = # PID of the console process
    signal.signal(signal.SIGTERM, watchdog_signal_handler)
    signal.signal(signal.SIGINT, watchdog_signal_handler)
    signal.signal(signal.SIGUSR1, watchdog_signal_handler)
    signal.signal(signal.SIGHUP, watchdog_signal_handler)
    signal.signal(signal.SIGABRT, watchdog_signal_handler)
    os.write(2, b'Console Watchdog started.\n')
    watchdog = ConsoleWatchdog(console_pid)
    watchdog.start()
    while True:
        try:
            time.sleep(30)
            os.kill(watchdog.watchdog_process.pid, signal.SIGINT)
        except Exception as e:
            os.write(2, f'Watchdog exception in main loop: {str(e)}\n'.encode())

if __name__ == '__main__':
    main()

