import csv
import logging
import random
import time
from datetime import datetime, timedelta
from logging.handlers import TimedRotatingFileHandler

from gpiozero import LED
from paho.mqtt import client as mqtt_client

class HydroponicsSystem:
    def __init__(self, config_file):
        self.config_file = config_file
        self.led = LED(17)
        self.log_file = "hydroponics_log.csv"
        self.system_log = "hydroponics_system.log"
        self.mqtt_client = None
        self.config = {
            "temperature": {"min": 18, "max": 25, "offset": 0.0, "gain": 1.0},
            "ph": {"min": 5.5, "max": 6.5, "offset": 0.0, "gain": 1.0},
            "ec": {"min": 1.0, "max": 2.0, "offset": 0.0, "gain": 1.0},
        }
        self.logger = logging.getLogger(__name__)
        handler = TimedRotatingFileHandler(
            self.system_log, when="midnight", backupCount=7
        )
        handler.setFormatter(
            logging.Formatter("%(asctime)s [%(levelname)s] %(message)s")
        )
        self.logger.addHandler(handler)
        self.logger.setLevel(logging.INFO)

    def parse_config(self):
        try:
            with open(self.config_file, "r") as file:
                lines = file.readlines()
                for line in lines:
                    sensor, value = line.strip().split("=")
                    for key, val in self.config.items():
                        if sensor == key:
                            val["min"], val["max"], val["offset"], val["gain"] = map(
                                float, value.split(",")
                            )
        except Exception as e:
            self.logger.error(f"Error parsing config file: {e}")

    def simulate_sensor_read(self, sensor):
        try:
            if sensor == "temperature":
                return random.uniform(15, 30)
            else:
                return random.uniform(1.0, 2.0)
        except Exception as e:
            self.logger.error(f"Error simulating sensor read: {e}")

    def check_sensor_limits(self, sensor, value):
        if (
            value < self.config[sensor]["min"]
            or value > self.config[sensor]["max"]
        ):
            self.logger.warning(f"{sensor.capitalize()} value {value} is out of limits")
            self.led.blink(1, 1, 3)

    def log_sensor_read(self, sensor, value):
        try:
            with open(self.log_file, "a") as file:
                writer = csv.writer(file)
                writer.writerow([datetime.now(), sensor, value])
        except Exception as e:
            self.logger.error(f"Error logging sensor read: {e}")

    def run(self):
        self.parse_config()
        while True:
            for sensor, values in self.config.items():
                value = self.simulate_sensor_read(sensor)
                self.check_sensor_limits(sensor, value)
                self.log_sensor_read(sensor, value)
            time.sleep(60)

if __name__ == "__main__":
    system = HydroponicsSystem("hydroponics_config.txt")
    try:
        system.run()
    except KeyboardInterrupt:
        system.led.off()
        system.logger.removeHandler(handler)

