import cv2
import serial
import sys
import time
import signal
from gpiozero import Button
from picamera2 import Picamera2, Preview
from adafruit_circuitplayground.express import cpx
from paho.mqtt import client as mqtt_client

class BallTracker:
    def __init__(self):
        self.picam = Picamera2()
        self.min_h = self.min_s = self.min_v = 0
        self.max_h = self.max_s = self.max_v = 255
        self.tracking = True
        self.ser = None
        self.button = Button(2)

    def start(self):
        self.picam.start()
        self.button.when_pressed = self.toggle_tracking

        ports = serial.tools.list_ports.comports()
        for p in ports:
            if self.ser is None:
                try:
                    self.ser = serial.Serial(p.device, 9600)
                except serial.SerialException:
                    print(f"Could not open serial port {p.device}")
            else:
                break

        if self.ser is None:
            print("Warning: No serial ports found.")

        while True:
            try:
                self.picam.capture_array(self.process_frame)
            except cv2.error:
                print("Error capturing frame.")
                break

    def process_frame(self, img):
        if not self.tracking:
            return img

        hsv = cv2.cvtColor(img, cv2.COLOR_BGR2HSV)
        mask = cv2.inRange(hsv, (self.min_h, self.min_s, self.min_v), (self.max_h, self.max_s, self.max_v))
        contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

        for cnt in contours:
            if cv2.contourArea(cnt) > 500:
                x, y, w, h = cv2.boundingRect(cnt)
                cv2.rectangle(img, (x, y), (x+w, y+h), (255, 0, 0), 2)
                self.send_position(x + w//2, y + h//2)

        return img

    def send_position(self, x, y):
        if self.ser is None:
            return

        try:
            if x > 320 - 50 and y > 240 - 50:
                if x > 320 + 50:
                    self.ser.write(b'1')
                elif x < 320 - 50:
                    self.ser.write(b'3')
                else:
                    self.ser.write(b'5')
            elif x > 320 - 50 and y < 240 + 50:
                if x > 320 + 50:
                    self.ser.write(b'2')
                elif x < 320 - 50:
                    self.ser.write(b'4')
                else:
                    self.ser.write(b'5')
            else:
                self.ser.write(b'5')
        except serial.SerialException:
            print("Error writing to serial port.")

    def toggle_tracking(self):
        self.tracking = not self.tracking

    def __del__(self):
        self.picam.stop()
        if self.ser is not None:
            self.ser.close()
        cv2.destroyAllWindows()

def on_signal(signum, frame):
    print("Signal handler (num=%d): shutting down..." % signum)
    del tracker
    sys.exit(0)

if __name__ == "__main__":
    tracker = BallTracker()
    signal.signal(signal.SIGINT, on_signal)
    signal.signal(signal.SIGTERM, on_signal)
    try:
        tracker.start()
    finally:
        del tracker

