class FanController:
    def __init__(self, pwm_pin=17, thresholds=[45, 50, 55, 65], pwm_values=[0.4, 0.6, 0.8, 1.0], default_pwm=1.0):
        if len(thresholds) != len(pwm_values):
            raise ValueError("Thresholds and PWM values arrays must be of equal length.")
        if not all(0.0 <= pwm <= 1.0 for pwm in pwm_values):
            raise ValueError("Each PWM value must lie in the range 0.0 to 1.0.")
        self.pwm_pin = pwm_pin
        self.thresholds = thresholds
        self.pwm_values = pwm_values
        self.default_pwm = default_pwm
        self.fan = None

    def __enter__(self):
        try:
            self.fan = PWMOutputDevice(self.pwm_pin, frequency=50)
            self.fan.value = self.default_pwm
            print("Startup: Running fan at default PWM.")
        except Device.PinInUse:
            print("Error: PWM pin in use.")
            exit(1)
        except Device.PinPermissionDenied:
            print("Error: Permission to use PWM pin denied.")
            exit(1)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.fan is not None:
            self.fan.value = self.default_pwm
            print("Shutdown: Running fan at default PWM.")
            self.fan.close()
