from paho.mqtt import client as mqtt_client

class MotionDetector:
    def __init__(self):
        self.picam2 = Picamera2()
        self.picam2.configure_camera_overrides(res="320x240")
        self.picam2.start()
        self.previous_frame = None
        self.frame_number = 0
        self.button = Button(27)

    def capture_frame(self):
        try:
            raw_frame = self.picam2.capture_array()
            frame = cv2.cvtColor(raw_frame, cv2.COLOR_BGR2GRAY)
            return frame
        except Exception as e:
            print(f"Error capturing frame: {e}")
            return None

    def blur_frame(self, frame):
        try:
            blur = cv2.GaussianBlur(frame, (3, 3), 0)
            return blur
        except Exception as e:
            print(f"Error blurring frame: {e}")
            return None

    def compensate_light(self, frame):
        try:
            compensated = cv2.equalizeHist(frame)
            return compensated
        except Exception as e:
            print(f"Error in light compensation: {e}")
            return None

    def compute_mse(self, frame1, frame2):
        try:
            mse = np.mean((frame1 - frame2) ** 2)
            return mse
        except Exception as e:
            print(f"Error computing MSE: {e}")
            return None

    def detect_motion(self):
        while True:
            if self.button.is_pressed:
                break
            frame = self.capture_frame()
            if frame is None:
                continue
            blur = self.blur_frame(frame)
            if blur is None:
                continue
            compensated = self.compensate_light(blur)
            if compensated is None:
                continue
            if self.previous_frame is not None:
                mse = self.compute_mse(compensated, self.previous_frame)
                if mse is None:
                    continue
                if mse > 100:
                    print(f"Motion detected using MSE in frame {self.frame_number}!")
            self.previous_frame = compensated
            self.frame_number += 1

    def __del__(self):
        self.picam2.stop()

if __name__ == "__main__":
    try:
        detector = MotionDetector()
        detector.detect_motion()
    except Exception as e:
        print(f"Error: {e}")
    finally:
        del detector

