import serial
import signal
from contextlib import suppress

class BluetoothSerial:
    def __init__(self, port, baudrate=38400):
        self.port = port
        self.baudrate = baudrate
        self.serial = None

    def __enter__(self):
        try:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=0)
        except serial.SerialException as e:
            print(f"Failed to open serial port {self.port}: {str(e)}", file=sys.stderr)
            sys.exit(1)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.serial is not None:
            self.serial.close()

    def write_line(self, line):
        if self.serial is not None:
            encoded_line = 'X' + line.rstrip() + '\n'
            encoded_line = encoded_line.encode('utf-8')
            bytes_sent = self.serial.write(encoded_line)
            print(f"Sent {bytes_sent} bytes", file=sys.stderr)
            return bytes_sent
        else:
            return 0

def handle_sigint(signum, frame):
    print("Got SIGINT, shutting down...", file=sys.stderr)
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, handle_sigint)

    with BluetoothSerial('/dev/rfcomm4') as bt_serial:
        while True:
            user_input = input("> ")
            if user_input == 'q':
                break
            bt_serial.write_line(user_input)

if __name__ == "__main__":
    main()

