                frame = self.temperature_frames[-1]
                plt.figure(figsize=(8, 8))
                plt.imshow(frame, cmap=cm.jet, interpolation='nearest')
                plt.colorbar()
                plt.title(f'Temperature at {time.ctime()}')
                plt.savefig('heatmap.png')
                plt.close()
                self.logger.debug('Visualized a temperature frame')
            except Exception as e:
