from adafruit_circuitpython_rgbmatrix import RGBMatrix
from paho.mqtt import client as mqtt_client

class AnimatedGif:
    def __init__(self, display, width=None, height=None, folder_path=None):
        self.display = display
        self.width = width or display.width
        self.height = height or display.height
        self.folder_path = folder_path
        self.gifs = []
        self._is_running = False

    def load_files(self):
        if not os.path.exists(self.folder_path):
            raise FileNotFoundError(f"No such directory: {self.folder_path}")

        for filename in os.listdir(self.folder_path):
            if filename.endswith(".gif"):
                try:
                    Image.open(os.path.join(self.folder_path, filename))
                    self.gifs.append(filename)
                except (IOError, ValueError) as e:
                    logging.warning(f"Invalid or corrupt GIF file: {filename}, error: {str(e)}")

        if not self.gifs:
            raise FileNotFoundError(f"No valid GIF files found in {self.folder_path}")

    def preload(self):
        for filename in self.gifs:
            try:
                gif = Image.open(os.path.join(self.folder_path, filename))
                duration = gif.info.get('duration', 100)
                loop_count = gif.info.get('loop', 0)
                frames = [frame.convert('RGB') for frame in gif.getframes()]
                self.gifs[filename] = {
                    'duration': duration,
                    'loop_count': loop_count,
                    'frames': frames
