# GPIO setup
Device.pin_factory = PiGPIOFactory()

# MQTT setup
broker_url = 'broker.hivemq.com'
client = mqtt_client.Client()

# Constants
LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75

def read_pi_temp():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, timeout=5)
        temp = float(result.stdout.split('=')[1].split("'")[0])
    except Exception as e:
        logging.warning(f"Failed to read Pi temperature: {e}")
        temp = None
    return temp

def simulate_light():
    try:
        light = cpx.light * 1000
        if 6 <= int(time.strftime('%H')) < 18:
            light = max(600, min(light, 1000))
        else:
            light = max(100, min(light, 300))
    except Exception as e:
        logging.warning(f"Failed to simulate light: {e}")
        light = 0
    return light

def simulate_temperature():
    try:
        temp = cpx.temperature
        temp = max(20, min(temp, 30))
    except Exception as e:
        logging.warning(f"Failed to simulate temperature: {e}")
        temp = 0
    return temp

def simulate_voltage_and_current(light):
    try:
        if light > 300:
            voltage = random.uniform(11.5, 12.5)
            current = random.uniform(1.5, 2.5)
        else:
            voltage = random.uniform(10.0, 11.0)
            current = random.uniform(0.5, 1.0)
    except Exception as e:
        logging.warning(f"Failed to simulate voltage and current: {e}")
        voltage = current = 0
    return voltage, current

def log_and_publish(light, temp, voltage, current, pi_temp):
    try:
        message = f"Light: {light} lux, Temperature: {temp}°C, Voltage: {voltage}V, Current: {current}A, Pi Temp: {pi_temp if pi_temp else 'N/A'}°C"
        logging.info(message)
        client.publish('energy_monitor', message)
    except Exception as e:
        logging.warning(f"Failed to log and publish data: {e}")

def main():
    try:
        while True:
            pi_temp = read_pi_temp()
            light = simulate_light()
            temp = simulate_temperature()
            voltage, current = simulate_voltage_and_current(light)
            if light < LOW_LIGHT_THRESHOLD:
                logging.warning(f"Low light warning! Current light level is {light} lux.")
            if temp > HIGH_TEMP_THRESHOLD:
                logging.warning(f"High temperature warning! Current temperature is {temp}°C.")
            if pi_temp and pi_temp > HIGH_PI_TEMP_THRESHOLD:
                logging.critical(f"High Pi temperature warning! Current Pi temperature is {pi_temp}°C. System shutdown simulated.")
                break
            log_and_publish(light, temp, voltage, current, pi_temp)
            time.sleep(5)
    except KeyboardInterrupt:
        logging.info("Gracefully terminating the program.")
    finally:
        client.disconnect()
        client.loop_stop()

