class SensorMonitor:
    def __init__(self):
        self.db = sqlite3.connect('environmental_data.db')
        self.cursor = self.db.cursor()
        self.cursor.execute('''CREATE TABLE IF NOT EXISTS environmental_data
                                    (timestamp, temperature, humidity)''')
        self.sensor = DHT22(4)
        self.sync_count = 0
        self.sync_max_attempts = 3
        self.sync_delay = 0.5
        self.sync_backoff_max = 30 * 60

    def read_sensor(self):
        try:
            temperature = self.sensor.temperature
            humidity = self.sensor.humidity
            return temperature, humidity
        except Exception as e:
            logging.warning(f"Sensor read failed: {e}")
            return None, None

    def write_to_db(self, timestamp, temperature, humidity):
        self.cursor.execute('''INSERT INTO environmental_data VALUES (?,?,?)''',
                            (timestamp, temperature, humidity))
        self.db.commit()

    def write_to_csv(self, filename, timestamp, temperature, humidity):
        with open(filename, 'a') as f:
            writer = csv.writer(f)
            if os.path.getsize(filename) == 0:
                writer.writerow(['timestamp', 'temperature', 'humidity'])
            writer.writerow([timestamp, temperature, humidity])

    def sync_to_cloud(self):
        try:
            response = requests.post('http://example.com/sync', json={'data': 'unsynced_data'})
            response.raise_for_status()
            self.sync_count = 0
            self.sync_delay = 0.5
            return True
        except requests.exceptions.RequestException as err:
            logging.warning(f"Sync failed: {err}")
            return False

    def check_internet(self):
        try:
            requests.get('https://www.google.com', timeout=5)
            return True
        except requests.exceptions.RequestException:
            return False

    def cleanup(self):
        self.sensor.close()
        self.db.close()

    def run(self):
        try:
            while True:
                temperature, humidity = self.read_sensor()
                if temperature is not None and humidity is not None:
                    timestamp = datetime.now().isoformat()
                    self.write_to_db(timestamp, temperature, humidity)
                    self.write_to_csv('environmental_data.csv', timestamp, temperature, humidity)
                    if self.sync_count >= self.sync_max_attempts and self.check_internet():
                        if self.sync_to_cloud():
                            self.write_to_csv('synced_data.csv', timestamp, temperature, humidity)
                        else:
                            self.sync_count += 1
                            self.sync_delay = min(self.sync_delay * 2, self.sync_backoff_max)
                    time.sleep(60)
        except KeyboardInterrupt:
            self.cleanup()

if __name__ == "__main__":
    SensorMonitor().run()

