import logging
import time
from bmp280 import BMP280, CalibrationError, OSError

# Set up logging
logging.basicConfig(level=logging.DEBUG)

# Default sea-level pressure
DEFAULT_SEA_LEVEL_PRESSURE_HPA = 1013.25

class BMP280Wrapper:
    def __init__(self, bus=1, sda=2, scl=3):
        self.bmp280 = None
        try:
            self.bmp280 = BMP280(bus=bus, sda=sda, scl=scl)
            self.calibrate()
        except (CalibrationError, OSError) as e:
            logging.error(f"Error initializing BMP280: {e}")

    def calibrate(self):
        samples = []
        for _ in range(100):
            samples.append(self.bmp280.pressure)
        samples.sort()
        trim = len(samples) // 4
        samples = samples[trim:-trim]
        self.baseline_pressure = sum(samples) / len(samples)

    def get_altitude(self):
        if self.bmp280 is None:
            return self.get_default_altitude()
        else:
            return self.bmp280.altitude(self.baseline_pressure)

    def get_default_altitude(self):
        return self.bmp280.altitude(DEFAULT_SEA_LEVEL_PRESSURE_HPA)

    def close(self):
        if self.bmp280 is not None:
            self.bmp280.close()


def main():
    bmp280_wrapper = BMP280Wrapper()
    try:
        while True:
            print(bmp280_wrapper.get_altitude())
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    finally:
        bmp280_wrapper.close()


if __name__ == "__main__":
    main()

