        self.motor = PWMOutputDevice(17, 18, 27)
        self.open_limit = Button(22)
        self.closed_limit = Button(23)
        self.temperature_sensor = DHT22()
        self.target_temperature = 25
        self.motor_state = 'stopped'

    def read_temperature(self):
        for _ in range(3):
            try:
                return self.temperature_sensor.read().temperature
            except RuntimeError:
                time.sleep(1)
        print('Failed to read temperature sensor')
        return None

    def control_motor(self, temperature):
        if self.open_limit.is_pressed or self.closed_limit.is_pressed:
            self.motor.stop()
            self.motor_state = 'stopped'
            print('Limit switch triggered, motor stopped')
        elif temperature > self.target_temperature and not self.open_limit.is_pressed:
            if self.motor_state != 'forward':
                self.motor.value = 0.5
                self.motor_state = 'forward'
                print('Temperature above target, vent opening')
        elif temperature < self.target_temperature and not self.closed_limit.is_pressed:
            if self.motor_state != 'backward':
                self.motor.value = -0.5
                self.motor_state = 'backward'
                print('Temperature below target, vent closing')
        else:
            if self.motor_state != 'stopped':
                self.motor.stop()
                self.motor_state = 'stopped'
                print('No action required, motor stopped')

    def run(self):
        while True:
            temperature = self.read_temperature()
            if temperature is not None:
                self.control_motor(temperature)
            time.sleep(5)

    def stop(self, signum, frame):
        self.motor.stop()
        print('Shutdown signal received, motor stopped')
        exit(0)


if __name__ == '__main__':
    system = VentilationSystem()
    for signum in (signal.SIGINT, signal.SIGTERM):
        signal.signal(signum, system.stop)
    system.run()

