class ThermalCamera:
    def __init__(self):
        self.ser = serial.Serial("/dev/ttyUSB0", 9600, timeout=0.1)
        self.data = []
        self.img = None
        self.fig = plt.figure(figsize=(4, 4))
        self.ax = self.fig.add_subplot(111)
        plt.ion()
        self.fig.show()

    def read_data(self):
        while True:
            try:
                line = self.ser.readline().decode()
                if not line:
                    continue
                if line.strip() == "":
                    continue
                data = list(map(int, line.strip().split(',')))
                if len(data) != 768:
                    continue
                self.data = data
            except (serial.SerialException, ValueError) as e:
                print(f"Error reading data: {e}")
                continue

    def display_data(self):
        while True:
            if self.data:
                if self.img is not None:
                    self.img.remove()
                self.img = self.ax.imshow(np.reshape(self.data, (24, 32)), 
                                          cmap='inferno', interpolation='nearest')
                plt.pause(0.1)

    def run(self):
        try:
            read_thread = gpiozero.Thread(target=self.read_data)
            display_thread = gpiozero.Thread(target=self.display_data)
            read_thread.start()
            display_thread.start()
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            print("\nExiting...")
        finally:
            self.ser.close()
            plt.close(self.fig)

if __name__ == "__main__":
    tc = ThermalCamera()
    tc.run()

