from gpiozero.pins.pcf import PCF8574

class MCP23017(I2C):
    def __init__(self, address=0x20, bus=None, **kwargs):
        super(MCP23017, self).__init__(address=address, bus=bus, **kwargs)

    def setup_gpio(self, pin, direction, pull_up):
        self._set_pin_dir(pin, direction)
        self._set_pin_pull_up(pin, pull_up)

    def _set_pin_dir(self, pin, direction):
        if direction == 'in':
            self._set_bit(self.IODIR, pin)
        elif direction == 'out':
            self._clear_bit(self.IODIR, pin)

    def _set_pin_pull_up(self, pin, pull_up):
        if pull_up:
            self._set_bit(self.GPPU, pin)
        else:
            self._clear_bit(self.GPPU, pin)

    def _set_bit(self, register, pin):
