            print(f"Error setting up GPIO: {e}")
            return False

        try:
            self.tft.init()
        except Exception as e:
            print(f"Error initializing TFT display: {e}")
            return False

        return True

    def draw_ascii(self, ascii_range):
        draw = ImageDraw.Draw(self.tft.image())
        for ascii_code in ascii_range:
            try:
                draw.text((0, 0), chr(ascii_code), font=self.tft.font, fill="white")
                self.tft.display()
                self.button.wait_for_press(2)
            except Exception as e:
                print(f"Error drawing ASCII character {ascii_code}: {e}")

    def draw_text(self, text, color, size):
        try:
            draw = ImageDraw.Draw(self.tft.image())
            draw.text((0, 0), text, font=self.tft.font(size), fill=color)
            self.tft.display()
            self.button.wait_for_press(3)
        except Exception as e:
            print(f"Error drawing text {text}: {e}")

    def draw_shapes(self):
