            draw.line((0, 128, 128, 0), fill="green")
            self.tft.display()
        except Exception as e:
            print(f"Error drawing shapes: {e}")

    def cleanup(self):
        if self.spi:
            self.spi.close()
        if self.led:
            self.led.off()

