class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.counter = 0
        self.clk_button = Button(clk_pin, pull_up=True)
        self.dt_button = Button(dt_pin, pull_up=True)
        self.clk_button.when_pressed = self.handle_event
        self.dt_button.when_pressed = self.handle_event
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def handle_event(self, pin):
        try:
            if self.clk_button.is_pressed and self.dt_button.is_pressed:
                if self.clk_button.values[0] == 1:
                    self.counter += 1
                else:
                    self.counter -= 1
                if callable(self.callback):
                    self.callback(self.counter)
        except (IOError, RuntimeError) as e:
            print(f"Error handling event: {e}")

    def cleanup(self, signum=None, frame=None):
        self.clk_button.when_pressed = None
        self.dt_button.when_pressed = None
        GPIO.remove_event_detect(self.clk_pin)
        GPIO.remove_event_detect(self.dt_pin)
        GPIO.cleanup()
        print("Cleaned up GPIO resources.")
        exit(0)

