    def print_counter(count):
        print(f"Counter: {count}")

    GPIO.setmode(GPIO.BCM)
    encoder = RotaryEncoder(17, 18, print_counter)
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
