from adafruit_circuitpython_mqtt import MQTT
from paho.mqtt.client import Client

class RotaryEncoderExtended(RotaryEncoder):
    def __init__(self, pin_clk=17, pin_dt=18, max_rate=0.005, 
                 active_low=False, partial=None, callback=None, 
                 debounce_interval=0.005, pin_factory=None):
        super().__init__(pin_clk, pin_dt, max_rate, active_low, partial, 
                         debounce_interval, pin_factory)
        self._callback = None
        self.value = 0
        if callback is not None:
            self.callback = callback
        self._last_clk_state = self.pin_clk.value
        self.pin_clk.when_activated = self._rotated
        self.pin_clk.when_deactivated = self._rotated

    @property
    def callback(self):
        return self._callback

    @callback.setter
    def callback(self, callback):
        if callable(callback):
            self._callback = callback
        else:
            raise ValueError('callback must be a callable function')

    def _rotated(self):
        try:
            if self.pin_dt.value != self._last_clk_state:
                self.value += 1
            else:
                self.value -= 1
            if self._callback is not None:
                self._callback(self.value)
        except Exception as e:
            print(f'Error in callback: {e}', file=sys.stderr)
        self._last_clk_state = self.pin_dt.value

    def cleanup(self):
        self.pin_clk.off()
        self.pin_dt.off()
        super().cleanup()

if __name__ == '__main__':
    try:
        def callback(value):
            print(f'Rotary encoder value: {value}')
            # Publish the value to MQTT topic
            client = Client()
            client.connect('mqtt.eclipse.org', 1883, 60)
            client.publish('topic', value)
            client.disconnect()

        encoder = RotaryEncoderExtended(callback=callback)
        while True:
            pass
    except KeyboardInterrupt:
        encoder.cleanup()
    except Exception as e:
        print(f'Error: {e}', file=sys.stderr)
        encoder.cleanup()

