import argparse
import datetime
import random
import time
import gpiozero
import paho.mqtt.client as mqtt

class RainwaterMonitor:
    def __init__(self, simulate, tank_height, tank_diameter):
        self.simulate = simulate
        self.tank_height = tank_height
        self.tank_diameter = tank_diameter
        self.sensor1 = gpiozero.DistanceSensor(echo=18, trigger=17, model='HC-SR04')
        self.sensor2 = gpiozero.DistanceSensor(echo=23, trigger=22, model='HC-SR04')
        self.mqtt_client = mqtt.Client()

    def get_distance(self, sensor):
        if self.simulate:
            return random.uniform(0.1, 0.9)
        try:
            distance = sensor.distance * 100
            if 2 <= distance <= 400:
                return distance
            else:
                print(f"Distance out of range: {distance}")
                return None
        except gpiozero.DistanceSensor.NoEchoError:
            print("Sensor read error: No echo received")
            return None

    def compute_volume(self, distance1, distance2):
        height = self.tank_height - distance1
        radius = self.tank_diameter / 2
        volume = 3.14159 * radius ** 2 * height
        return round(volume, 2)

    def run(self):
        try:
            while True:
                distance1 = self.get_distance(self.sensor1)
                distance2 = self.get_distance(self.sensor2)
                if distance1 is not None and distance2 is not None:
                    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    print(f"{timestamp}: Sensor1: {distance1}, Sensor2: {distance2}, Volume: {self.compute_volume(distance1, distance2)}")
                time.sleep(5)
        except KeyboardInterrupt:
            self.sensor1.close()
            self.sensor2.close()

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--simulate", action="store_true")
    parser.add_argument("--tank_height", type=float, required=True)
    parser.add_argument("--tank_diameter", type=float, required=True)
    args = parser.parse_args()

    if args.tank_height <= 0 or args.tank_diameter <= 0:
        print("Tank height and diameter must be positive")
        exit(1)

    monitor = RainwaterMonitor(args.simulate, args.tank_height, args.tank_diameter)
    monitor.run()

