server.bind(('127.0.0.1', 9099))
server.listen(5)

# Initialize the MQTT client
client = mqtt_client.Client()

def read_gps_position():
    try:
        fix = gps.wait_for_fix(2)
        if fix:
            return fix.latitude, fix.longitude
        else:
            return 0, 0
    except Exception as e:
        sys.stderr.write(f"Failed to read GPS position: {e}\n")
        return 0, 0

def handle_command(command):
    if command == "start":
        gps.start()
    elif command == "stop":
        gps.stop()
    elif command == "report":
        lat, lon = read_gps_position()
        return {"lat": lat, "lon": lon}
    else:
        raise ValueError("Invalid command")

def main():
    while True:
        try:
            client, address = server.accept()
            data = client.recv(1024).decode()
            try:
                response = handle_command(data)
                if response:
                    client.send(json.dumps(response).encode())
            except ValueError as e:
                sys.stderr.write(str(e))
            finally:
                client.close()
        except socket.error as e:
            sys.stderr.write(f"Socket error: {e}\n")

def cleanup(signal, frame):
    gps.close()
    server.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    main()
```

This script initializes a TCP server that accepts commands from clients and performs actions based on these commands. The GPS module is read using the gpiozero library, and the server is implemented using the built-in socket library. The script also includes a cleanup function that is called when the program receives a SIGINT or SIGTERM signal, ensuring that the GPS module and TCP server are properly shut down.

