import logging
import sys
from gpiozero import OutputDevice
from paho.mqtt import client as mqtt_client

class Actuator:
    def __init__(self, bcm_pin):
        self.device = OutputDevice(bcm_pin)

    def on(self):
        self.device.on()

    def off(self):
        self.device.off()

    def close(self):
        self.device.close()

class IntentClassifier:
    def __init__(self):
        self.intents = {
            'pump_on': ['pump on', 'turn pump on'],
            'pump_off': ['pump off', 'turn pump off'],
            'light_toggle': ['light toggle', 'switch the light']
        }

    def classify(self, phrase):
        for intent, phrases in self.intents.items():
            if phrase.lower() in phrases:
                return intent
        return None

class IoTDevice:
    def __init__(self, bcm_pin, mqtt_client):
        self.actuator = Actuator(bcm_pin)
        self.classifier = IntentClassifier()
        self.mqtt_client = mqtt_client

    def handle_phrase(self, phrase):
        intent = self.classifier.classify(phrase)
        if intent is None:
            logging.warning(f'Unknown command: {phrase}')
            self.mqtt_client.publish('warning', f'Unknown command: {phrase}')
        else:
            logging.info(f'{phrase} -> {intent}')
            self.mqtt_client.publish('intent', intent)
            if intent == 'pump_on':
                self.actuator.on()
            elif intent == 'pump_off':
                self.actuator.off()
            elif intent == 'light_toggle':
                self.actuator.device.toggle()

    def close(self):
        self.actuator.off()
        self.actuator.close()

def main():
    logging.basicConfig(level=logging.INFO)
    mqtt_client = mqtt_client.Client()
    device = IoTDevice(20, mqtt_client)
    phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]
    try:
        for phrase in phrases:
            device.handle_phrase(phrase)
    except Exception as e:
        logging.error(f'Error: {e}')
        device.close()
        sys.exit(1)
    except KeyboardInterrupt:
        logging.info('Exiting on user request')
        device.close()
        sys.exit(0)

if __name__ == "__main__":
    main()

