            self.ser.close()


def parse_gps_data(data):
    if data is None:
        return None, None
    if not data.startswith('$GPRMC'):
        return None, None
    parts = data.split(',')
    if parts[2] != 'A':
        return None, None
    lat = parts[3]
    lat_dir = parts[4]
    lon = parts[5]
    lon_dir = parts[6]
    if lat == '' or lon == '':
        return None, None
    lat = float(lat[:2]) + float(lat[2:]) / 60
    if lat_dir == 'S':
        lat = -lat
    lon = float(lon[:3]) + float(lon[3:]) / 60
    if lon_dir == 'W':
        lon = -lon
    return lat, lon


