import time
import threading
import serial
import serial.tools.list_ports
from datetime import datetime

class FlowReader:
    def __init__(self, port, baudrate, timeout):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.stop_event = threading.Event()
        self.serial_instance = None

    def open_serial(self):
        try:
            self.serial_instance = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
        except serial.SerialException as e:
            print(f"Failed to open serial port: {e}")
            return False
        return True

    def close_serial(self):
        if self.serial_instance is not None:
            self.serial_instance.close()

    def read_loop(self):
        while not self.stop_event.is_set():
            try:
                line = self.serial_instance.readline().decode('utf-8', 'replace').strip()
                flow_rate = float(line)
                print(f"Flow Rate: {flow_rate} L/min")
                with open('water_flow_log.txt', 'a') as f:
                    f.write(f"{datetime.now().isoformat()} - Flow Rate: {flow_rate} L/min\n")
            except ValueError:
                print(f"Warning: Could not convert {line} to a numeric value.")
            except serial.SerialException as e:
                print(f"I/O error: {e}")
                return
            time.sleep(1)

    def start(self):
        if not self.open_serial():
            return
        self.read_thread = threading.Thread(target=self.read_loop)
        self.read_thread.start()

    def stop(self):
        self.stop_event.set()
        self.read_thread.join()
        self.close_serial()

if __name__ == "__main__":
    reader = FlowReader('/dev/ttyUSB0', 9600, 1)
    try:
        reader.start()
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Stopping reader...")
    finally:
        reader.stop()
