class ESP8266:
    def __init__(self, port='/dev/ttyAMA0', baudrate=115200, timeout=5, write_timeout=5, read_timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.write_timeout = write_timeout
        self.read_timeout = read_timeout
        self.max_retries = 3
        self._setup_serial()

    def _setup_serial(self):
        try:
            self.serial = serial.Serial(port=self.port, baudrate=self.baudrate, timeout=self.timeout, write_timeout=self.write_timeout)
        except serial.SerialException as e:
            print(f"Error setting up serial: {e}")
            raise

    def _send_command(self, command, delay=1, max_retries=3):
        for i in range(max_retries):
            try:
                self.serial.write(command.encode('utf-8') + b'\r\n')
                time.sleep(delay)
                response = self._read_response()
                if response is not None:
                    return response
            except (serial.SerialException, serial.SerialTimeoutException) as e:
                print(f"Error sending command: {e}")
        return None

    def _read_response(self):
        try:
            response = self.serial.read_until(b'\r\n', self.read_timeout)
            return response.decode('utf-8').strip()
        except (serial.SerialException, serial.SerialTimeoutException) as e:
            print(f"Error reading response: {e}")
            return None

