import logging
import time
import serial
import serial.tools.list_ports

class SimpleGPS:
    def __init__(self):
        self.uart = None

    def connect(self):
        try:
            self.uart = serial.Serial('/dev/serial0', 9600)
            return True
        except OSError:
            logging.error('Failed to open UART port', exc_info=True)
            return False

    def read_data(self):
        if self.uart is None or not self.uart.isOpen():
            return None
        try:
            line = self.uart.readline().decode('utf-8', 'ignore').strip()
            return line
        except (OSError, serial.SerialException):
            logging.error('Failed to read data from UART', exc_info=True)
            return None

    def parse_gga(self, line):
        try:
            fields = line.split(',')
            talker_id = fields[0][3:5]
            if talker_id not in ('GP', 'GN'):
                return None
            utc_time = fields[1]
            latitude = float(fields[2]) if fields[2] else None
            longitude = float(fields[4]) if fields[4] else None
            fix_quality = int(fields[6]) if fields[6] else None
            num_satellites = int(fields[7]) if fields[7] else None
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites,
            }
        except (IndexError, ValueError):
            logging.error('Failed to parse GGA sentence', exc_info=True)
            return None

    def close(self):
        if self.uart is not None and self.uart.isOpen():
            try:
                self.uart.close()
            except Exception:
                logging.error('Failed to close UART port', exc_info=True)

if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    gps = SimpleGPS()
    if gps.connect():
        try:
            while True:
                line = gps.read_data()
                if line is not None and line.startswith('$GPGGA') or line.startswith('$GNGGA'):
                    parsed = gps.parse_gga(line)
                    if parsed is not None:
                        logging.info(parsed)
        except KeyboardInterrupt:
            pass
    gps.close()

