        self.port = port
        self.baudrate = baudrate
        self.ser = None

    def __enter__(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate)
        except serial.SerialException as e:
            print(f"Error opening serial port: {e}")
            sys.exit(1)
        return self

