import sys
import time
import serial
from gpiozero import LED
from picamera2 import Picamera2, Preview
from adafruit_circuitpython_rfcomm import RFCOMMDevice
from paho.mqtt import client as mqtt_client

class BluetoothConnection:
    def __init__(self, device_path, baudrate):
        self.device_path = device_path
        self.baudrate = baudrate
        self.connection = None

    def connect(self):
        try:
            self.connection = RFCOMMDevice(self.device_path, self.baudrate)
        except Exception as e:
            raise RuntimeError(f"Failed to connect to Bluetooth device: {e}")

    def send(self, message):
        try:
            self.connection.write(message.encode())
            time.sleep(0.1)
        except Exception as e:
            raise RuntimeError(f"Failed to send message to Bluetooth device: {e}")

    def close(self):
        if self.connection:
            self.connection.close()

class RaspberryPiEmbedded:
    def __init__(self):
        self.bluetooth = BluetoothConnection('/dev/rfcomm4', 38400)
        self.led = LED(17)
        self.picamera2 = Picamera2()
        self.mqtt = mqtt_client.Client()

    def run(self):
        try:
            self.bluetooth.connect()
            self.led.on()
            self.picamera2.start()
            while True:
                command = input("Enter command: ")
                if command == "exit":
                    break
                self.bluetooth.send(f"X{command}\n")
        except KeyboardInterrupt:
            print("\nExiting gracefully...")
        except RuntimeError as e:
            print(e)
        finally:
            self.led.off()
            self.picamera2.stop()
            self.bluetooth.close()

if __name__ == "__main__":
    RaspberryPiEmbedded().run()

